  "required": [
    "version",
    "projection",
    "defaults",
    "provenance",
    "generated_state",
    "transformations",
    "ownership",
    "publication_policy",
    "mirror",
    "derive",
    "live",
    "editorial",
    "exclude",
    "selected_excluded_inputs",
    "eventing",
    "reconciliation",
    "freshness",
    "deletion",
    "conflicts",
    "manifest",
    "invariants"
  ],
  "properties": {
